# fig2.R -- cross-cancer heterogeneity: 31 x 7 HR matrix + pooled strip + cell counts
#
# Rebuilt on patchwork (declarative row stacking).  The previous version drew the
# whole page in ONE coordinate system with 31 hand-placed annotate() calls: the
# legend sat at data y = -9.4, row labels were text at x = 0.52, and the panel had
# to run clip = "off" to push the germ-layer names outside the data range.
# Two consequences were measurable:
#   * the size legend drew precision = 5 at a diameter 18 % larger than the scale
#     actually produced (now the legend is generated by the scale itself, in a
#     dedicated panel, so it cannot drift from the encoding);
#   * "1.5 mm up-left" rendered as 7.5 mm left / 1.2 mm up, because one x unit is
#     19.8 mm while one y unit is 3.8 mm (now every offset goes through dx()/dy()).
#
# One column, five rows: all panels share the same width, and the label gutter lives
# inside the shared x range as negative x.
source("scripts/figs/00_tokens.R")
source("scripts/figs/01_data.R")
suppressPackageStartupMessages(library(patchwork))

# ---------------- page geometry (mm) --------------------------------------
W_TOT <- 183; H_TOT <- 216
M_EDGE <- 4
W_GUTTER <- 19
H_HEAD <- 15; H_MAT <- 127; H_CNT <- 9; H_STR <- 34; H_LEG <- 18
PANEL_W <- W_TOT - 2 * M_EDGE

# ---------------- row order: germ block, then stromal effect descending ----
GAP <- 1.0
strm <- aggregate(beta ~ cancer, data = d[d$signature %in% SIG_STROMA, ], FUN = mean)
names(strm)[2] <- "stroma_beta"
cm2 <- merge(cm, strm, by = "cancer", sort = FALSE)
cm2 <- cm2[order(as.integer(cm2$germ_layer), -cm2$stroma_beta), ]
n <- nrow(cm2)
cm2$y[1] <- n + 2 * GAP
for (i in 2:n) cm2$y[i] <- cm2$y[i - 1] - 1 -
  ifelse(cm2$germ_layer[i] != cm2$germ_layer[i - 1], GAP, 0)

YLIM <- c(min(cm2$y) - 0.62, max(cm2$y) + 0.62)

XP <- c(1, 2, 3, 4, 5.65, 6.65, 7.65); names(XP) <- SIG_ORDER
X_MAT <- c(0.38, 8.28)

# One x unit = (panel width - gutter) / matrix span, so the gutter is exactly 19 mm.
MM_X <- (PANEL_W - W_GUTTER) / diff(X_MAT)
GUT <- W_GUTTER / MM_X
XLIM <- c(X_MAT[1] - GUT, X_MAT[2])
MM_Y <- H_MAT / diff(YLIM)

dx <- function(mm) mm / MM_X
dy <- function(mm) mm / MM_Y

X_GERM_LAB <- XLIM[1] + dx(2.2)
X_GERM_BAR <- c(XLIM[1] + dx(4.0), XLIM[1] + dx(5.5))
X_ROWLAB   <- X_MAT[1] - dx(1.3)

dd <- merge(d, cm2[, c("cancer", "y", "germ_layer")], by = "cancer", sort = FALSE)
dd$x <- XP[dd$signature]
dd$l2 <- log2(dd$HR)
dd$ring <- ifelse(dd$sig, "sig", "ns")

ph$y <- cm2$y[match(ph$cancer, cm2$cancer)]
ph$x <- XP[ph$signature]
phv <- ph[ph$ph_viol & !is.na(ph$y), ]

lab_cells <- rbind(
  data.frame(cancer = c("GBM", "OV", "UVM", "CESC", "LGG", "SARC"),
             signature = c("CD8_Tcell", "CD8_Tcell", "TLS", "TLS", "IFNg_path", "IFNg_path")),
  oor[, c("cancer", "signature")]
)
lab <- merge(lab_cells, dd[, c("cancer", "signature", "x", "y", "HR")],
             by = c("cancer", "signature"), sort = FALSE)
lab$x <- lab$x + dx(2.75)

germ_band <- do.call(rbind, lapply(GERM_ORDER, function(g) {
  yy <- cm2$y[as.character(cm2$germ_layer) == g]
  data.frame(germ = g, ymid = (min(yy) + max(yy)) / 2,
             ylo = min(yy) - 0.46, yhi = max(yy) + 0.46, stringsAsFactors = FALSE)
}))
germ_band$lab <- c(endoderm = "Endoderm", mesoderm = "Mesoderm",
                   ectoderm = "Ectoderm")[germ_band$germ]
stopifnot(nrow(germ_band) == 3, !any(is.na(germ_band$lab)))

cm2$rowlab <- paste0(cm2$cancer, ifelse(cm2$deaths <= 10, "\u2020", ""))

# ---------------- pooled strip geometry -----------------------------------
# This panel has its own y scale (log10 HR), so its mm conversion must use its own
# height -- using the matrix's dy() here made the diamonds 70 % of the axis span.
YR <- log10(c(0.80, 1.50)) + c(-0.013, 0.015)
MM_Y_STR <- H_STR / diff(YR)
dy_str <- function(mm) mm / MM_Y_STR
ystr <- function(hr) log10(hr)
dw <- dx(2.8); dh <- dy_str(0.36)

diamonds <- do.call(rbind, lapply(seq_len(nrow(pooled)), function(i) {
  x <- XP[[as.character(pooled$signature[i])]]; y0 <- ystr(pooled$HR[i])
  data.frame(x = c(x - dw, x, x + dw, x), y = c(y0, y0 + dh, y0, y0 - dh),
             id = i, signature = pooled$signature[i])
}))
seg <- data.frame(x = XP[as.character(pooled$signature)],
                  y1 = ystr(pooled$lo), y2 = ystr(pooled$hi))
axis_breaks <- c(0.85, 1.00, 1.20, 1.50)

# ---------------- shared theme + shared scales ----------------------------
# The scales are defined once and reused by the legend panel, so the keys cannot
# drift from the encoding they explain.
SIZE_MAX <- 3.0          # mm diameter at the top of the precision range
SIZE_LIM <- c(0, 16.8)   # 1/SE range across the 217 estimates
size_mm <- function(v) SIZE_MAX * sqrt(v / SIZE_LIM[2])   # area-proportional

th_void <- theme_void(base_family = "Arial") +
  theme(plot.margin = margin(0, M_EDGE, 0, M_EDGE, unit = "mm"),
        plot.background = element_rect(fill = "white", colour = NA),
        panel.background = element_rect(fill = "white", colour = NA))

sc_fill <- function(guide = "none") scale_fill_hr_bin(guide = guide)
sc_size <- function(guide = "none") {
  scale_size_area(max_size = SIZE_MAX, limits = SIZE_LIM, breaks = c(4, 8, 12, 16),
                  name = "Precision (1/SE)", guide = guide)
}
sc_col <- function(guide = "none") {
  scale_colour_manual(values = c(sig = PAL$ink, ns = PAL$ring_ns),
                      labels = c(sig = "p < 0.05", ns = "p \u2265 0.05"),
                      name = NULL, guide = guide)
}
sc_shape <- function(guide = "none") {
  scale_shape_manual(values = c("PH violated" = 17), name = NULL, guide = guide)
}

# ======================= row 1: column group headers ======================
p_head <- ggplot() +
  annotate("rect", xmin = 0.42, xmax = 4.50, ymin = 0.40, ymax = 1.04,
           fill = PAL$band, colour = NA) +
  annotate("rect", xmin = 5.22, xmax = 8.24, ymin = 0.40, ymax = 1.04,
           fill = PAL$band, colour = NA) +
  annotate("text", x = (0.42 + 4.50) / 2, y = 0.72, label = "Immune signatures",
           size = fsp(FS$label), fontface = "bold", colour = PAL$ink) +
  annotate("text", x = (5.22 + 8.24) / 2, y = 0.72, label = "Stromal / proliferation",
           size = fsp(FS$label), fontface = "bold", colour = PAL$ink) +
  annotate("text", x = XP, y = 0.14, label = SIG_ORDER,
           size = fsp(FS$label), fontface = "bold", colour = PAL$ink) +
  coord_cartesian(xlim = XLIM, ylim = c(0, 1.10), expand = FALSE) +
  th_void + theme(plot.margin = margin(M_EDGE, M_EDGE, 0, M_EDGE, unit = "mm"))

# ======================= row 2: the matrix ================================
p_mat <- ggplot() +
  annotate("rect", xmin = X_GERM_BAR[1], xmax = X_GERM_BAR[2],
           ymin = germ_band$ylo, ymax = germ_band$yhi,
           fill = GERM_COL[germ_band$germ], colour = NA) +
  annotate("text", x = X_GERM_LAB, y = germ_band$ymid, label = germ_band$lab,
           angle = 90, size = fsp(FS$foot), colour = PAL$ink2) +
  annotate("text", x = X_ROWLAB, y = cm2$y, label = cm2$rowlab,
           hjust = 1, size = fsp(FS$tick), colour = PAL$ink) +
  geom_point(data = dd, aes(x = x, y = y, size = invse, fill = l2, colour = ring),
             shape = 21, stroke = STROKE[["disc"]]) +
  geom_point(data = phv, aes(x = x - dx(1.55), y = y + dy(1.15), shape = "PH violated"),
             size = 0.62, colour = PAL$ink) +
  geom_text(data = lab, aes(x = x, y = y, label = sprintf("%.2f", HR)),
            size = fsp(FS$cell), colour = PAL$ink2, hjust = 0, vjust = 0.5) +
  sc_fill() + sc_col() + sc_size() + sc_shape() +
  coord_cartesian(xlim = XLIM, ylim = YLIM, expand = FALSE) +
  th_void

# ======================= row 3: significant-cell counts ===================
p_cnt <- ggplot() +
  annotate("segment", x = X_MAT[1], xend = X_MAT[2], y = 0.96, yend = 0.96,
           linewidth = lw(LW$thin), colour = PAL$ns) +
  annotate("text", x = X_ROWLAB, y = 0.44,
           label = "Significant cells\n(protective / risk)", hjust = 1, vjust = 0.5,
           size = fsp(FS$foot), colour = PAL$ink2, lineheight = 0.92) +
  annotate("text", x = XP, y = 0.44,
           label = paste0(sig_tab$prot, " / ", sig_tab$risk),
           size = fsp(FS$stat), colour = PAL$ink) +
  coord_cartesian(xlim = XLIM, ylim = c(0, 1), expand = FALSE) +
  th_void

# ======================= row 4: pooled hazard ratios ======================
p_str <- ggplot() +
  geom_segment(data = seg, aes(x = x, xend = x, y = y1, yend = y2),
               linewidth = lw(LW$ci), colour = PAL$ink) +
  geom_polygon(data = diamonds, aes(x = x, y = y, group = id),
               fill = PAL$ink, colour = NA) +
  annotate("segment", x = X_MAT[1], xend = X_MAT[2], y = 0, yend = 0,
           linewidth = lw(LW$ref), linetype = "22", colour = PAL$ref) +
  annotate("segment", x = X_GERM_BAR[2] + dx(1.2), xend = X_GERM_BAR[2] + dx(2.4),
           y = ystr(axis_breaks), yend = ystr(axis_breaks),
           linewidth = lw(LW$edge), colour = PAL$ink) +
  annotate("text", x = X_GERM_BAR[2] + dx(0.6), y = ystr(axis_breaks),
           label = sprintf("%.2f", axis_breaks),
           hjust = 1, size = fsp(FS$tick), colour = PAL$ink) +
  annotate("text", x = X_GERM_LAB - dx(1.2), y = mean(ystr(c(0.85, 1.20))), label = "Pooled HR",
           angle = 90, size = fsp(FS$foot), colour = PAL$ink2) +
  annotate("text", x = XP, y = max(YR) - dy_str(0.55),
           label = sprintf("I\u00b2 = %.1f%%", pooled$I2),
           size = fsp(FS$stat), colour = PAL$ink2) +
  annotate("text", x = XP, y = min(YR) + dy_str(0.65),
           label = fmt_hr(pooled$HR, pooled$lo, pooled$hi),
           size = fsp(FS$cell), colour = PAL$ink) +
  coord_cartesian(xlim = XLIM, ylim = YR, expand = FALSE) +
  th_void

# ======================= row 5: legend panel ==============================
# Drawn in millimetres on its own canvas rather than handed to patchwork's guide
# collector: patchwork 1.3.0 + ggplot2 4.0.4 collects guides to the patch margin and
# ignores legend.position, which either pushed the legend to the right (stealing 40 %
# of the width) or dropped it entirely.  Every key below is computed from the same
# SIZE_MAX / SIZE_LIM / PAL$hr_bins constants the matrix uses, so the key cannot
# disagree with the encoding the way the old hand-drawn legend did (18 % off).
LEG_W <- PANEL_W; LEG_H <- 18
LEG_Y1 <- 12.6; LEG_Y2 <- 4.2
BIN_W <- 11.8; BIN_H <- 3.0; BIN_X0 <- 1.5
X_PREC <- 96

leg_bins <- data.frame(
  xmin = BIN_X0 + (0:5) * BIN_W,
  fill = PAL$hr_bins,
  lab  = c("\u2264 0.67", "0.67\u20130.80", "0.80\u20131.00",
           "1.00\u20131.25", "1.25\u20132.00", "> 2.00"),
  stringsAsFactors = FALSE
)
leg_prec <- data.frame(v = c(4, 8, 12, 16))
leg_prec$x <- X_PREC + (seq_len(nrow(leg_prec)) - 1) * 9.5
leg_prec$d <- size_mm(leg_prec$v)

p_leg <- ggplot() +
  # hazard-ratio bins
  annotate("text", x = BIN_X0, y = LEG_Y1 + 3.3, label = "Hazard ratio",
           hjust = 0, size = fsp(FS$label), colour = PAL$ink) +
  annotate("rect", xmin = leg_bins$xmin, xmax = leg_bins$xmin + BIN_W - 0.2,
           ymin = LEG_Y1 - BIN_H / 2, ymax = LEG_Y1 + BIN_H / 2,
           fill = leg_bins$fill, colour = NA) +
  annotate("text", x = leg_bins$xmin + (BIN_W - 0.2) / 2, y = LEG_Y1 - 3.1,
           label = leg_bins$lab, size = fsp(FS$foot), colour = PAL$ink2) +
  # precision, diameters taken from the same area mapping as scale_size_area
  annotate("text", x = X_PREC, y = LEG_Y1 + 3.3, label = "Precision (1/SE)",
           hjust = 0, size = fsp(FS$label), colour = PAL$ink) +
  annotate("point", x = leg_prec$x, y = LEG_Y1, size = leg_prec$d,
           shape = 21, fill = PAL$ns, colour = PAL$ink2, stroke = STROKE[["disc"]]) +
  annotate("text", x = leg_prec$x, y = LEG_Y1 - 3.1, label = leg_prec$v,
           size = fsp(FS$foot), colour = PAL$ink2) +
  # significance ring and PH marker
  annotate("point", x = c(3.2, 23.2), y = LEG_Y2, size = 2.6, shape = 21,
           fill = PAL$ns, colour = c(PAL$ink, PAL$ring_ns),
           stroke = c(STROKE[["ring_sig"]], STROKE[["ring_ns"]])) +
  annotate("text", x = c(5.4, 25.4), y = LEG_Y2,
           label = c("p < 0.05", "p \u2265 0.05"), hjust = 0,
           size = fsp(FS$foot), colour = PAL$ink2) +
  annotate("point", x = 44.0, y = LEG_Y2, shape = 17, size = 1.15, colour = PAL$ink) +
  annotate("text", x = 46.2, y = LEG_Y2, label = "PH violated", hjust = 0,
           size = fsp(FS$foot), colour = PAL$ink2) +
  annotate("text", x = 66.0, y = LEG_Y2, label = NOTE_DEATHS, hjust = 0,
           size = fsp(FS$foot), colour = PAL$ink2) +
  coord_cartesian(xlim = c(0, LEG_W), ylim = c(0, LEG_H), expand = FALSE) +
  th_void + theme(plot.margin = margin(0, M_EDGE, M_EDGE, M_EDGE, unit = "mm"))

# ======================= assemble =========================================
p <- (p_head / p_mat / p_cnt / p_str / p_leg) +
  plot_layout(heights = c(H_HEAD, H_MAT, H_CNT, H_STR, H_LEG), guides = "keep")

save_fig(p, "Fig2_heterogeneity", W_TOT, H_TOT)
cat("Fig2 saved:", nrow(dd), "cells,", nrow(phv), "PH markers,", nrow(lab),
    "value labels,", nrow(pooled), "pooled estimates\n")
cat("  MM_X =", round(MM_X, 2), "mm/unit | MM_Y(mat) =", round(MM_Y, 2),
    "| MM_Y(str) =", round(MM_Y_STR, 2), "| gutter =", W_GUTTER, "mm\n")
